import{_ as e,l as p,o,b as c,q as l,d as a,f as t,m as d}from"./chunks/framework.Tf23FRXt.js";const r="/assets/HiddenGorgemap.2TOSedY5.png",g="/assets/towerhp.NNt5ihgk.jpg",n="/assets/hgteamlist.DukbzHmo.png",v="/assets/hghud.HhmdG2YX.jpg",_="/assets/hgcore.BI_XNHOS.png",h="/assets/hgtower.8ZU0agjt.png",u="/assets/hg1.CyusU-JL.png",m="/assets/hg2.B_iUJpnc.png",w="/assets/hg3.Bzw_Ogm7.png",x="/assets/hgs1.CFdApPM2.png",b="/assets/hgs2.CjKwcphq.png",T="/assets/goblinmercenary.B7FKY3sZ.jpg",k="/assets/hgtrain.BWQl7u54.jpg",j=JSON.parse('{"title":"烈羽争锋","description":"","frontmatter":{},"headers":[{"level":2,"title":"界面介绍","slug":"界面介绍","link":"#界面介绍","children":[]},{"level":2,"title":"机制介绍","slug":"机制介绍","link":"#机制介绍","children":[{"level":3,"title":"胜利条件","slug":"胜利条件","link":"#胜利条件","children":[]},{"level":3,"title":"机动兵器","slug":"机动兵器","link":"#机动兵器","children":[]},{"level":3,"title":"青鳞水","slug":"青鳞水","link":"#青鳞水","children":[]},{"level":3,"title":"非玩家单位","slug":"非玩家单位","link":"#非玩家单位","children":[]},{"level":3,"title":"战意","slug":"战意","link":"#战意","children":[]},{"level":3,"title":"新人小贴士","slug":"新人小贴士","link":"#新人小贴士","children":[]}]}],"relativePath":"topic/rivalwings.htm.md","filePath":"topic/rivalwings.md","lastUpdated":1791101830000}'),S={name:"topic/rivalwings.htm.md"};function N(f,i,B,C,V,A){const s=p("Status");return o(),c("div",null,[i[3]||(i[3]=l('<h1 id="烈羽争锋" tabindex="-1">烈羽争锋</h1><p>目前，烈羽争锋仅开放了隐塞的地图。</p><h2 id="界面介绍" tabindex="-1">界面介绍</h2><div class="guide cols4 base"><div class="guide col"><img src="'+r+'" width="200px"><p>隐塞地图</p></div><div class="guide col"><img src="'+g+'" width="200px"><p>核心塔和防御塔的血量。</p></div><div class="guide col"><img src="'+n+'" width="200px"><p>团队列表，标有战意及青磷水持有量</p></div><div class="guide col"><img src="'+v+'"><p>任务面板，可以看到小队战意及青鳞水状况、<br>同时包含了每个阵营剩余的防御塔数量及机甲出库情况</p></div></div><h2 id="机制介绍" tabindex="-1">机制介绍</h2><h3 id="胜利条件" tabindex="-1">胜利条件</h3><p>破坏掉敌方据点中的 “核心”。</p><p>若在限制时间内双方的核心都没有被破坏，则依次依据对核心伤害量、残存防御塔数量、对防御塔伤害量进行胜利方的判定。</p><p>在这些条件都相同时，会计算平局，但是与战场不同的是，隐塞的不分胜负不会计入胜场。</p><div class="guide cols2"><div class="guide col"><img src="'+_+'" width="350px"><p>核心</p></div><div class="guide col grow"><p>核心设置在各阵营据点中的破坏目标，防御塔未破坏前，无法对核心造成伤害。</p></div></div><div class="guide cols2"><div class="guide col"><img src="'+h+'" width="350px"><p>防御塔</p></div><div class="guide col grow"><p>每个阵营各配置有两座防御塔。防御塔拥有塔结界（圆形区域），可以提供体力恢复和减伤。破坏掉敌方防御塔可以提高我方团队的战意。</p></div></div><h3 id="机动兵器" tabindex="-1">机动兵器</h3><p>机甲是由玩家所搭乘强大兵器。共有 3 种性能不同的机体：</p><div class="guide cols3"><div class="guide col"><img src="'+u+'" width="300px"><p>巡航驱逐者（1 号机）</p></div><div class="guide col"><img src="'+m+'" width="300px"><p>压迫者（2 号机）</p></div><div class="guide col grow"><img src="'+w+'" width="300px"><p>残暴正义号（3 号机）</p></div></div><ul><li>巡航驱逐者，一般被称为一号机：1 技能对机甲造成大量伤害，2 技能对玩家目标造成大量伤害，3 技能为远程技能，对玩家和机甲伤害一般</li><li>压迫者，一般称为二号机，可以对防御塔和核心造成巨大伤害</li><li>残暴正义号，一般称为三号机：1 技能对玩家、小兵、机甲、建筑均可造成大量伤害，3 技能是超远距离的大伤害直线技能</li></ul><p>机甲在烈羽争锋的战斗中十分重要，因此也包含有诸多的限制：</p><ol><li>每个小队同时只能有 1 名玩家搭乘 1 台机甲。</li><li>启动机甲需要 50 点青磷水。</li><li>机甲不能接受任何治疗。</li><li>整个团队只能同时启动 2 台压迫者。</li><li>仅仅在防御塔被破坏后，团队才会获得 1 次残暴正义号的驾驶机会，因此，不熟练的萌新请慎重驾驶以免造成队友的血压上升！</li></ol><h3 id="青鳞水" tabindex="-1">青鳞水</h3><p>由于机甲需要青磷水能量才能启动，因此青鳞水是也是烈羽争锋中重要的一环！在破坏了敌人的自走人偶后，每个小队最多可以收集 100 点青鳞水，请善加利用吧～</p><p>青鳞水的获得条件：</p><ul><li>在水区采集青鳞水罐：10</li><li>破坏自走人偶（根据伤害量分配）：最大 20</li><li>破坏哥布林坦克（根据伤害量分配）：最大 20</li><li>大容量青磷水罐：50</li><li>哥布式大份套餐：50</li></ul><h3 id="非玩家单位" tabindex="-1">非玩家单位</h3><div class="guide cols2"><div class="guide col"><img src="'+x+'" width="350px"><p>自走维京人偶</p></div><div class="guide col"><img src="'+b+'" width="350px"><p>自走法师人偶</p></div></div><p>自走人偶，一般被称为小兵、兵线。</p><p>自走人偶虽然不会攻击玩家，但一旦到达防御塔或核心，会自爆造成大量伤害，请务必注意敌方与我方的兵线位置！</p><div class="guide cols2"><div class="guide col"><img src="'+T+'" width="350px"><p>哥布林佣兵</p></div><div class="guide col grow"><p>随着烈羽争锋的进行，场地会在南北随机刷新一名哥布林佣兵，通过两阵营对其造成的伤害进行判定，进而与一方结下契约。哥布林佣兵会提供巨大的帮助。</p></div></div><div class="guide cols2"><div class="guide col"><img src="'+k+'" width="350px"><p>青磷引擎车（俗称火车）</p></div><div class="guide col grow"><p>火车会在滴滴滴的预告后以超高速行驶出现在战场！随后停靠在车站，占领后即可获取火车携带的物资！</p><p>但是请注意，高速行驶的火车会秒杀途径的所有单位，请一定注意交通安全！不要卧轨或者被火车撞飞哦～</p></div></div><p>青磷引擎车会携带多种物资，物资不仅会带来帮助，还会为团队全体提升 1 点战意，请善用这些物资为自己取得胜利吧！</p><ul><li>大容量青磷水罐：阵营所有小队各增加 50 青鳞水。</li><li>哥布式兴奋剂：阵营所有玩家的奋战槽（6.1 前设定，6.1 后由于 pvp 改版，暂时未知）提高到最大。</li><li>哥布林坦克认证钥匙：获得两路出击的强力帮手哥布林坦克</li><li>哥布式大份套餐：同时获得以上所有效果，仅会在战斗的后期出现哦</li></ul><h3 id="战意" tabindex="-1">战意</h3>',30)),a("p",null,[i[0]||(i[0]=t("打倒敌方、摧毁防御塔后会赋予全小队的",-1)),d(s,{id:1465,name:"气势"}),i[1]||(i[1]=t("，给予不同程度的伤害量、恢复魔法、恢复能力的恢复量提高的效果。当档数达到 20 时，气势会变为",-1)),d(s,{id:1730,name:"气势高昂"}),i[2]||(i[2]=t("。",-1))]),i[4]||(i[4]=l('<p>在搭乘机甲时气势是没有效果的哦～</p><div class="md-table"><table class="ui compact grey striped unstackable table"><thead><tr><th>获取气势的方式</th><th>获取对象及气势数值</th></tr></thead><tbody><tr><td>打倒气势 0-9 的敌方</td><td>小队 1</td></tr><tr><td>打倒气势 10-19 的敌方</td><td>小队 2</td></tr><tr><td>打倒满气势敌方</td><td>小队 3</td></tr><tr><td>破坏敌方防御塔</td><td>团队 1</td></tr><tr><td>哥布林坦克认证密钥</td><td>团队 1</td></tr><tr><td>大容量青磷水罐</td><td>团队 1</td></tr><tr><td>哥布式兴奋剂</td><td>团队 1</td></tr><tr><td>哥布式大份套餐</td><td>团队 3</td></tr></tbody></table></div><p>与纷争前线不同，在烈羽争锋中死亡不会损失气势。</p><h3 id="新人小贴士" tabindex="-1">新人小贴士</h3><ol><li>原则上机甲能出就出，一号机主要处理敌方机甲，同时配合步兵处理兵线；二号机不要打人，不要打人，不要打人；三号机是烈羽争锋中最为重要的机甲之一且作用复杂，需要拥有对战斗局势的理解与判断，请各位萌新再更多了解之后再尝试三号机吧～</li><li>在己方防御塔内拥有高额减伤，如果面对敌人是劣势状态，可以试着回到塔的防御范围内进行战斗</li><li>烈羽争锋不要轻言放弃，随时都有翻盘的可能，挂机和家里打字键盘喷人都是被唾弃的行为哦！</li><li>如果你选择了做一名水工，请注意青鳞水有上限，不要满 100 点后依然在做无意义的工作。同时，在满足己方出机甲的情况下，水工也需要经常支援步兵哦！</li><li>你在纷争前线中学会的集火与单点技巧，均可以使用到烈羽争锋的战斗中来。</li><li>隐塞本质是推塔游戏，一味地杀爽了并不一定能为你带来胜利，请多与队友交流配合，感受属于烈羽争锋的快乐吧！</li></ol>',5))])}const y=e(S,[["render",N]]);export{j as __pageData,y as default};
